package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.dto.Requests.RiskRuleRequest;import com.example.riskplatform.entity.RiskRule;import com.example.riskplatform.service.RiskRuleService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/risk-rules") @RequiredArgsConstructor public class RiskRuleController{private final RiskRuleService s;@GetMapping @PreAuthorize("hasAuthority('rule:read')")public ApiResponse<List<RiskRule>>list(){return ApiResponse.ok(s.list());}@PostMapping @PreAuthorize("hasAuthority('rule:write')")public ApiResponse<RiskRule>create(@Valid @RequestBody RiskRuleRequest r){return ApiResponse.ok(s.create(r));}@PutMapping("/{id}") @PreAuthorize("hasAuthority('rule:write')")public ApiResponse<RiskRule>update(@PathVariable Long id,@Valid @RequestBody RiskRuleRequest r){return ApiResponse.ok(s.update(id,r));}@DeleteMapping("/{id}") @PreAuthorize("hasAuthority('rule:write')")public ApiResponse<Void>delete(@PathVariable Long id){s.delete(id);return ApiResponse.ok();}}